// TH14 synthetic bullet aliases used by this card (see transcribe/th14/touhou-bullets.ecl).
// Native type 8 -> TH14_RICE; source type 0..23 maps to the same target slot.
const TH14_RICE: int = 480;

// TH14 v1.00b st07.ecl::MainSub07 (src939-961) + GirlA01 closure (src159-205).
// Scope: A group only, 4 rounds x (8 left enmCreate + 8 right enmCreateM), 64 spawns total.
// GirlA02 tail (src962-971) and MainSub07_472's fall-through are outside this card.
// Card frame 0 = selected entry; source schedule starts after the 120-frame opening buffer.

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// src GirlA01_at2 (186-205): etNew/etAim/etSprite/etCount/etAngle/etSpeed then 100x(etOn, wait10).
// mode0 fan, N=1, M=2: each wave aims once at the player and emits layer0 speed5 then layer1 speed4.
async sub girl_shoot() {
    for i in 0..100 {
        var aim: angle = aim_player();   // src wave-start A, shared by both layers
        var dx: fx = cos(aim);
        var dy: fx = sin(aim);
        // src etSprite(0,8,6): type 8 -> TH14_RICE, color 6.
        // ANIM slot0 a=1 birth recoil kept: spawn position -= 4*initial_speed along angle.
        _ = fire(TH14_RICE, 6, $self_x-20fx*dx, $self_y-20fx*dy, 5fx, aim, none, none);
        _ = fire(TH14_RICE, 6, $self_x-16fx*dx, $self_y-16fx*dy, 4fx, aim, none, none);
        // ANIM visual birth slowdown and EX slot1 SPEEDUP(async=1, params -999999) are
        // birth-stage effects with no target equivalent; omitted per approved policy.
        wait(10);                        // src etOn(0); wait(10)
    }
}

// src GirlA01 (159-167) + GirlA01_at (169-184). mirror=1 for enmCreateM children.
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                   // src setHurtbox(24,24); ordinary circle = width*0.5
    set_hitbox(8fx);                     // src setHitbox(16,16); body collision kept
    spawn girl_shoot();                  // src @GirlA01_at2() async
    // Mirror is applied at explicit angle writes: theta -> 180deg - theta (x negated).
    var a_mid: angle = -2048 as angle;   // src moveVelTime(120,1,-0.19634955,3.0)
    var a_end: angle = 2048 as angle;    // src moveVelTime(60,4,0.19634955,4.0)
    if mirror != 0 {
        a_mid = 34816 as angle;          // 180deg - (-11.25deg)
        a_end = 30720 as angle;          // 180deg - 11.25deg
    }
    move_vel(0, 90deg, 4fx, EASE_LINEAR);       // src moveVel(1.5707964,4.0) = ABS 90deg
    move_vel(120, a_mid, 3fx, EASE_QUAD_IN);    // src mode1 -> EASE_QUAD_IN
    wait(120);
    move_vel(60, a_end, 4fx, EASE_QUAD_OUT);    // src mode4 -> EASE_QUAD_OUT
    loop { wait(1000); }                        // src GirlA01_at_248 permanent wait
}

// src MainSub07 (939-961): each round is 8x15 + 8x15 + 50 = 290 frames.
async sub pattern() {
    wait(OPENING_BUFFER);
    for cycle in 0..4 {
        for i in 0..8 {
            _ = spawn_enemy(-140fx, -32fx, 90, 0, 1000, 0, girl(0));  // src enmCreate at (-140,-32)
            wait(15);
        }
        for j in 0..8 {
            _ = spawn_enemy(140fx, -32fx, 90, 0, 1000, 0, girl(1));   // src enmCreateM at (140,-32)
            wait(15);
        }
        wait(50);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
